PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS brands(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,name TEXT NOT NULL,niche TEXT NOT NULL,target_audience TEXT NOT NULL,persona TEXT NOT NULL,tone TEXT NOT NULL,language TEXT NOT NULL DEFAULT 'pt-BR',editorial_aggressiveness TEXT NOT NULL CHECK(editorial_aggressiveness IN('LOW','MEDIUM','HIGH')),controversy_appetite TEXT NOT NULL CHECK(controversy_appetite IN('LOW','MEDIUM','HIGH')),virality_priority TEXT NOT NULL,freshness_priority TEXT NOT NULL,factual_invention_tolerance TEXT NOT NULL DEFAULT 'ZERO',preferred_topics TEXT NOT NULL DEFAULT '',avoided_topics TEXT NOT NULL DEFAULT '',preferred_vocabulary TEXT NOT NULL DEFAULT '',avoided_vocabulary TEXT NOT NULL DEFAULT '',cta_preferences TEXT NOT NULL DEFAULT '',target_platforms TEXT NOT NULL,content_objectives TEXT NOT NULL DEFAULT '',default_formats TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,brand_id TEXT NOT NULL REFERENCES brands(id) ON DELETE CASCADE,name TEXT NOT NULL,type TEXT NOT NULL,url TEXT,enabled INTEGER NOT NULL DEFAULT 1,priority INTEGER NOT NULL DEFAULT 50 CHECK(priority BETWEEN 0 AND 100),reliability INTEGER NOT NULL DEFAULT 50 CHECK(reliability BETWEEN 0 AND 100),category TEXT NOT NULL,metadata TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS source_items(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id) ON DELETE CASCADE,external_id TEXT,title TEXT NOT NULL,url TEXT,published_at TEXT,discovered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,author TEXT,summary TEXT NOT NULL,raw_metadata TEXT NOT NULL DEFAULT '{}',processing_status TEXT NOT NULL DEFAULT 'NEW',provenance_group TEXT,UNIQUE(source_id,external_id));
CREATE TABLE IF NOT EXISTS topics(id TEXT PRIMARY KEY,brand_id TEXT NOT NULL REFERENCES brands(id) ON DELETE CASCADE,title TEXT NOT NULL,summary TEXT NOT NULL,category TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'MONITORING',first_detected_at TEXT NOT NULL,last_information_at TEXT NOT NULL,original_published_at TEXT,collected_at TEXT NOT NULL,freshness TEXT NOT NULL,virality_score INTEGER NOT NULL CHECK(virality_score BETWEEN 0 AND 100),confidence_score INTEGER NOT NULL CHECK(confidence_score BETWEEN 0 AND 100),momentum_score INTEGER NOT NULL CHECK(momentum_score BETWEEN 0 AND 100),saturation_risk INTEGER NOT NULL CHECK(saturation_risk BETWEEN 0 AND 100),editorial_priority_score INTEGER NOT NULL CHECK(editorial_priority_score BETWEEN 0 AND 100),signals TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS topic_source_items(topic_id TEXT NOT NULL REFERENCES topics(id) ON DELETE CASCADE,source_item_id TEXT NOT NULL REFERENCES source_items(id) ON DELETE CASCADE,is_primary INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(topic_id,source_item_id));
CREATE TABLE IF NOT EXISTS ideas(id TEXT PRIMARY KEY,topic_id TEXT NOT NULL REFERENCES topics(id) ON DELETE CASCADE,title TEXT NOT NULL,angle TEXT NOT NULL,rationale TEXT NOT NULL DEFAULT '',rank_score INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'DRAFT',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contents(id TEXT PRIMARY KEY,brand_id TEXT NOT NULL REFERENCES brands(id),topic_id TEXT NOT NULL REFERENCES topics(id),idea_id TEXT NOT NULL REFERENCES ideas(id),title TEXT NOT NULL,thesis TEXT NOT NULL,angle TEXT NOT NULL,master_hook TEXT NOT NULL,master_script TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'DRAFT',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hook_candidates(id TEXT PRIMARY KEY,content_id TEXT NOT NULL REFERENCES contents(id) ON DELETE CASCADE,text TEXT NOT NULL,hook_type TEXT NOT NULL,hook_score INTEGER NOT NULL CHECK(hook_score BETWEEN 0 AND 100),selected INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS factual_claims(id TEXT PRIMARY KEY,content_id TEXT NOT NULL REFERENCES contents(id) ON DELETE CASCADE,claim_text TEXT NOT NULL,confidence TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'UNVERIFIED');
CREATE TABLE IF NOT EXISTS claim_supports(claim_id TEXT NOT NULL REFERENCES factual_claims(id) ON DELETE CASCADE,source_item_id TEXT NOT NULL REFERENCES source_items(id),PRIMARY KEY(claim_id,source_item_id));
CREATE TABLE IF NOT EXISTS content_variants(id TEXT PRIMARY KEY,content_id TEXT NOT NULL REFERENCES contents(id) ON DELETE CASCADE,platform TEXT NOT NULL,hook TEXT NOT NULL,script TEXT NOT NULL,title TEXT NOT NULL,caption TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',hashtags TEXT NOT NULL DEFAULT '',cta TEXT NOT NULL DEFAULT '',target_duration INTEGER,visual_direction TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'DRAFT',UNIQUE(content_id,platform));
CREATE TABLE IF NOT EXISTS social_accounts(id TEXT PRIMARY KEY,brand_id TEXT NOT NULL REFERENCES brands(id),platform TEXT NOT NULL,username TEXT NOT NULL,display_name TEXT NOT NULL,external_account_id TEXT,connection_status TEXT NOT NULL DEFAULT 'DISCONNECTED',metadata TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS publications(id TEXT PRIMARY KEY,content_variant_id TEXT NOT NULL REFERENCES content_variants(id),social_account_id TEXT REFERENCES social_accounts(id),scheduled_for TEXT,published_at TEXT,external_post_id TEXT,status TEXT NOT NULL DEFAULT 'DRAFT',retry_count INTEGER NOT NULL DEFAULT 0,error TEXT,metadata TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS editorial_feedback(id TEXT PRIMARY KEY,content_id TEXT NOT NULL REFERENCES contents(id),action TEXT NOT NULL,reason TEXT,note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,content_variant_id TEXT REFERENCES content_variants(id),type TEXT NOT NULL,source TEXT NOT NULL,license_provenance TEXT,storage_location TEXT NOT NULL,metadata TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS metric_snapshots(id TEXT PRIMARY KEY,publication_id TEXT NOT NULL REFERENCES publications(id),captured_at TEXT NOT NULL,views INTEGER,impressions INTEGER,likes INTEGER,comments INTEGER,shares INTEGER,saves INTEGER,watch_time REAL,average_watch_time REAL,completion_rate REAL,followers_generated INTEGER,clicks INTEGER,metadata TEXT NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS idx_topics_hot ON topics(brand_id,editorial_priority_score DESC); CREATE INDEX IF NOT EXISTS idx_source_items_discovered ON source_items(discovered_at DESC); CREATE INDEX IF NOT EXISTS idx_publications_schedule ON publications(status,scheduled_for); CREATE INDEX IF NOT EXISTS idx_contents_status ON contents(status);
